const tr = (locale: Locale, text: string) => supplementalCopy[locale]?.[text] ?? copy[locale][text] ?? text;
function localizeTree(node: ReactNode, locale: Locale): ReactNode {
  if (typeof node === "string") {
    const trimmed=node.trim();
    return trimmed ? node.replace(trimmed,tr(locale,trimmed)) : node;
  }
  if (Array.isArray(node)) return node.map(child=>localizeTree(child,locale));
  if (!isValidElement(node)) return node;
  const element=node as ReactElement<{children?:ReactNode;[key:string]:unknown}>;
  const props={...element.props};
  for (const key of ["placeholder","aria-label","title","alt"]) if (typeof props[key]==="string") props[key]=tr(locale,props[key] as string);
  return cloneElement(element,props,localizeTree(element.props.children,locale));
}
function Localized({locale,children}:{locale:Locale;children:ReactNode}) { return <>{localizeTree(children,locale)}</>; }

const stages = ["Inquiry", "Order details", "Payment", "Packing", "Shipped"];
const stageFor = (status: string) => {
  if (status === "SHIPPED" || status === "COMPLETED") return 4;
  if (status === "PACKING") return 3;
  if (status === "PAID") return 2;
  if (status === "AWAITING_PAYMENT") return 2;
  if (status === "DETAILS_REQUESTED" || status === "AWAITING_CONFIRMATION") return 1;
  return 0;
};
const statusLabel = (status: string) => status.replaceAll("_", " ").toLowerCase();

